const REACT_ITEMS = REACTIONS.map(([r, right, w1, w2, w3, lv, why]) => mk(+lv, 'reactions of carbonyl compounds and acids', `The main organic product of ${F(r.replace(/ with /, ' with '))} is`, F(right), [F(w1), F(w2), F(w3)], S(why, `Product: <b>${F(right)}</b>.`), +lv >= 3 ? 'Check where the reaction stops and which atom the new group is placed on.' : ''));

// 3. tests: compound | formula | flags | kind.   flags: i iodoform, t Tollens, f Fehling, d 2,4-DNP, a aldol (needs a-H), c Cannizzaro
const CMP = [
  ['ethanal', 'CH3CHO', 'itfda', 'aliphatic aldehyde with a CH3CO&ndash; unit and &alpha;-H'],
  ['propanal', 'CH3CH2CHO', 'tfda', 'aliphatic aldehyde with &alpha;-H, no CH3CO&ndash; unit'],
  ['methanal', 'HCHO', 'tfdc', 'aldehyde with no &alpha;-H'],
  ['benzaldehyde', 'C6H5CHO', 'tdc', 'aromatic aldehyde with no &alpha;-H'],
  ['propanone', 'CH3COCH3', 'ida', 'ketone with a CH3CO&ndash; unit and &alpha;-H'],
  ['butanone', 'CH3COCH2CH3', 'ida', 'methyl ketone with &alpha;-H'],
  ['pentan-2-one', 'CH3COCH2CH2CH3', 'ida', 'methyl ketone with &alpha;-H'],
  ['pentan-3-one', 'CH3CH2COCH2CH3', 'da', 'ketone with &alpha;-H but no CH3CO&ndash; unit'],
  ['acetophenone', 'C6H5COCH3', 'ida', 'aromatic methyl ketone'],
  ['benzophenone', 'C6H5COC6H5', 'd', 'diaryl ketone with no &alpha;-H'],
  ['cyclohexanone', 'C6H10O (cyclohexanone)', 'da', 'cyclic ketone with &alpha;-H and no CH3CO&ndash; unit'],
  ['ethanol', 'CH3CH2OH', 'i', 'alcohol that oxidises to ethanal (CH3CH(OH)&ndash; unit)'],
  ['propan-2-ol', '(CH3)2CHOH', 'i', 'alcohol that oxidises to propanone (CH3CH(OH)&ndash; unit)'],
  ['propan-1-ol', 'CH3CH2CH2OH', '', 'primary alcohol with no CH3CH(OH)&ndash; unit'],
  ['methanol', 'CH3OH', '', 'simplest alcohol'],
  ['2,2-dimethylpropanal', '(CH3)3CCHO', 'tfdc', 'aliphatic aldehyde with no &alpha;-H'],
  ['2-methylpropanal', '(CH3)2CHCHO', 'tfda', 'aliphatic aldehyde with one &alpha;-H'],
  ['phenylethanal', 'C6H5CH2CHO', 'tfda', 'aliphatic aldehyde with &alpha;-H'],
  ['methanoic acid', 'HCOOH', 'tf', 'acid with an aldehyde-type H'],
  ['ethanoic acid', 'CH3COOH', '', 'carboxylic acid with no aldehydic H'],
  ['butan-2-ol', 'CH3CH(OH)CH2CH3', 'i', 'alcohol with a CH3CH(OH)&ndash; unit'],
].map(([n, f, fl, k]) => ({ n, f, fl, k, lab: `${F(f)} (${n})` }));
const TESTS = [
  { t: 'i', lv: 2, name: 'the iodoform test (a yellow precipitate with I2 and NaOH)', rule: 'Iodoform needs a CH<sub>3</sub>CO&ndash; group (or a CH<sub>3</sub>CH(OH)&ndash; group, which the reagent first oxidises to CH<sub>3</sub>CO&ndash;).' },
  { t: 't', lv: 2, name: 'a silver mirror with Tollens&rsquo; reagent', rule: 'Tollens&rsquo; reagent oxidises aldehydes (aliphatic and aromatic) and methanoic acid. Ketones, alcohols and ordinary acids do not react.' },
  { t: 'f', lv: 3, name: 'a red precipitate with Fehling&rsquo;s solution', rule: 'Fehling&rsquo;s solution oxidises aliphatic aldehydes (and methanoic acid) only. Aromatic aldehydes and ketones do not reduce it.' },
  { t: 'd', lv: 1, name: 'an orange-yellow precipitate with 2,4-dinitrophenylhydrazine', rule: '2,4-DNP condenses with the C=O group of any aldehyde or ketone. Alcohols and acids do not respond.' },
  { t: 'a', lv: 3, name: 'the aldol reaction in dilute NaOH', rule: 'The aldol reaction needs an aldehyde or ketone that has at least one &alpha;-hydrogen.' },
  { t: 'c', lv: 3, name: 'the Cannizzaro reaction in conc. NaOH', rule: 'Cannizzaro needs an aldehyde with no &alpha;-hydrogen (HCHO, aromatic aldehydes, R<sub>3</sub>C&ndash;CHO).' },
];
const TEST_ITEMS = [];
for (const T of TESTS) {
  const Pp = CMP.filter((c) => c.fl.includes(T.t)), Nn = CMP.filter((c) => !c.fl.includes(T.t));
  const more = (arr, start, step, k, skip = []) => { const out = []; for (let i = 0; out.length < k && i < 200; i++) { const c = arr[(start + i * step) % arr.length]; if (!out.includes(c) && !skip.includes(c)) out.push(c); } for (const c of arr) { if (out.length >= k) break; if (!out.includes(c) && !skip.includes(c)) out.push(c); } return out; };
  const why = (c) => `${c.lab}: ${c.k}`;
  for (let j = 0; j < 6; j++) {
    const right = Pp[(j * 3 + 1) % Pp.length]; const wr = more(Nn, j * 2 + 1, 5, 3);
    TEST_ITEMS.push(mk(T.lv, 'tests for carbonyl compounds', `Which of the following gives ${T.name}?`, right.lab, wr.map((c) => c.lab), S(T.rule, `<b>${why(right)}</b>: it fits.`, `Not suitable: ${wr.map(why).join('; ')}.`)));
  }
  for (let j = 0; j < 2; j++) {
    const right = Nn[(j * 4 + 2) % Nn.length]; const wr = more(Pp, j + 1, 2, 3);
    TEST_ITEMS.push(mk(T.lv + (j ? 1 : 0), 'tests for carbonyl compounds', `Which of the following does NOT give ${T.name}?`, right.lab, wr.map((c) => c.lab), S(T.rule, `<b>${why(right)}</b>: it does not fit.`, `The others do give the result: ${wr.map(why).join('; ')}.`), 'A &ldquo;does NOT&rdquo; question: three options are positive and one is negative.'));
  }
}
// pairs that a chemical test can separate
for (const T of TESTS.filter((x) => 'itfc'.includes(x.t))) {
  const diff = [], same = [];
  for (let a = 0; a < CMP.length; a++) for (let b = a + 1; b < CMP.length; b++) { const A = CMP[a], B = CMP[b]; (A.fl.includes(T.t) !== B.fl.includes(T.t) ? diff : same).push([A, B]); }
  const nm = { i: 'the iodoform test', t: 'Tollens&rsquo; reagent', f: 'Fehling&rsquo;s solution', c: 'the Cannizzaro reaction (conc. NaOH)' }[T.t];
  for (let j = 0; j < 3; j++) {
    const right = diff[(j * 37 + 5) % diff.length]; const ws = []; for (let i = 0; ws.length < 3 && i < 300; i++) { const w = same[(j * 11 + i * 17 + 3) % same.length]; if (!ws.includes(w)) ws.push(w); }
    const pr = (p) => `${p[0].lab} and ${p[1].lab}`; const res = (p) => `${p[0].n}: ${p[0].fl.includes(T.t) ? 'positive' : 'negative'}, ${p[1].n}: ${p[1].fl.includes(T.t) ? 'positive' : 'negative'}`;
    TEST_ITEMS.push(mk(3, 'distinguishing tests', `Which pair can be distinguished by ${nm}?`, pr(right), ws.map(pr), S(T.rule, `<b>${res(right)}</b>: they differ, so the test separates them.`, `Other pairs behave the same: ${ws.map(res).join('; ')}.`)));
  }
}

// 4. acids ranked by pKa: [label, pKa] listed from strongest to weakest, with the reason for the order
const ACIDS = [
  ['Chloro-substituted ethanoic acids', 'each extra Cl withdraws electrons (&minus;I effect) and stabilises the anion', [['CH3COOH', 4.76], ['ClCH2COOH', 2.86], ['Cl2CHCOOH', 1.29], ['Cl3CCOOH', 0.65]], 1],
  ['Alkyl-substituted acids', 'alkyl groups push electrons (+I effect), destabilise the anion and weaken the acid; H has no such effect', [['HCOOH', 3.75], ['CH3COOH', 4.76], ['CH3CH2COOH', 4.87], ['(CH3)3CCOOH', 5.03]], 1],
  ['Para-substituted benzoic acids', 'NO<sub>2</sub> withdraws electrons; CH<sub>3</sub> and OCH<sub>3</sub> donate (OCH<sub>3</sub> by resonance)', [['p-O2NC6H4COOH', 3.44], ['C6H5COOH', 4.20], ['p-CH3C6H4COOH', 4.37], ['p-CH3OC6H4COOH', 4.47]], 2],
  ['Halogenated ethanoic acids', 'the more electronegative the halogen, the stronger its &minus;I effect', [['FCH2COOH', 2.66], ['ClCH2COOH', 2.86], ['BrCH2COOH', 2.90], ['ICH2COOH', 3.16]], 3],
  ['Chlorobutanoic acids', 'the &minus;I effect weakens as the Cl moves further from COOH', [['CH3CH2CHClCOOH', 2.84], ['CH3CHClCH2COOH', 4.06], ['ClCH2CH2CH2COOH', 4.52], ['CH3CH2CH2COOH', 4.82]], 3],
  ['Chlorobenzoic acids', 'm-Cl has only the &minus;I effect; p-Cl also has a weak +R effect that partly cancels it; H has neither', [['m-ClC6H4COOH', 3.83], ['p-ClC6H4COOH', 3.98], ['C6H5COOH', 4.20], ['p-CH3C6H4COOH', 4.37]], 3],
  ['Nitrobenzoic acids', 'the NO<sub>2</sub> group helps most at the ortho position (ortho effect and &minus;I), less at para', [['o-O2NC6H4COOH', 2.17], ['p-O2NC6H4COOH', 3.44], ['C6H5COOH', 4.20], ['p-CH3OC6H4COOH', 4.47]], 3],
  ['Acids and acid-like compounds', 'an acid is stronger the more stable its conjugate base; carboxylate is resonance stabilised, carbonate less so, phenoxide less still, alkoxide not at all', [['CH3COOH', 4.76], ['H2CO3', 6.35], ['C6H5OH (phenol)', 10.0], ['CH3CH2OH', 16]], 2],
  ['Methylbenzoic acids', 'the ortho isomer is strongest (ortho effect); methyl is a donor at meta and para', [['o-CH3C6H4COOH', 3.91], ['C6H5COOH', 4.20], ['m-CH3C6H4COOH', 4.27], ['p-CH3C6H4COOH', 4.37]], 4],
  ['Unsaturated and saturated acids', 'a more s-rich sp carbon withdraws electrons most; sp<sup>2</sup> carbon next; sp<sup>3</sup> carbon least', [['HC&equiv;CCOOH', 1.84], ['CH2=CHCOOH', 4.25], ['CH3COOH', 4.76], ['CH3CH2COOH', 4.87]], 4],
  ['Dicarboxylic acids (first dissociation)', 'the second COOH is an electron-withdrawing group and the effect fades with the distance between the two groups', [['HOOC&ndash;COOH', 1.25], ['HOOC&ndash;CH2&ndash;COOH', 2.85], ['HOOC(CH2)2COOH', 4.21], ['HOOC(CH2)4COOH', 4.43]], 4],
  ['Acids with other strong groups', 'a strongly electron-withdrawing group (NO<sub>2</sub>, CN, Cl) beside COOH helps most; OCH<sub>3</sub> only a little', [['O2NCH2COOH', 1.68], ['NCCH2COOH', 2.47], ['ClCH2COOH', 2.86], ['CH3OCH2COOH', 3.57]], 4],
  ['Strongly acidic compounds', 'three nitro groups make picric acid as strong as a mineral acid; the carboxylates follow the usual rules; a simple nitrophenol is far weaker', [['2,4,6-trinitrophenol', 0.4], ['HCOOH', 3.75], ['C6H5COOH', 4.20], ['p-nitrophenol', 7.15]], 5],
];
const strip = (s) => F(s);
const ACID_ITEMS = [];
for (const [title, why, list, lv] of ACIDS) {
  const names = list.map((x) => strip(x[0]));
  const tab = list.map((x) => `${strip(x[0])} (pKa ${x[1]})`).join('; ');
  const shuffled = [list[2], list[0], list[3], list[1]];
  const qlist = shuffled.map((x, i) => `(${'abcd'[i]}) ${strip(x[0])}`).join(', ');
  const L = (x) => 'abcd'[shuffled.indexOf(x)];
  ACID_ITEMS.push(mk(lv, 'acidity of carboxylic acids', `${title}: which is the strongest acid? ${qlist}.`, `(${L(list[0])}) ${strip(list[0][0])}`, [list[1], list[2], list[3]].map((x) => `(${L(x)}) ${strip(x[0])}`), S(`Compare the stability of the conjugate bases: ${why}.`, `pKa values: ${tab}. The smallest pKa is the strongest acid: <b>${strip(list[0][0])}</b>.`), 'A smaller pKa means a stronger acid.'));
  ACID_ITEMS.push(mk(lv, 'acidity of carboxylic acids', `${title}: which is the weakest acid? ${qlist}.`, `(${L(list[3])}) ${strip(list[3][0])}`, [list[0], list[1], list[2]].map((x) => `(${L(x)}) ${strip(x[0])}`), S(`Compare the stability of the conjugate bases: ${why}.`, `pKa values: ${tab}. The largest pKa is the weakest acid: <b>${strip(list[3][0])}</b>.`), 'A larger pKa means a weaker acid.'));
  ACID_ITEMS.push(ord(lv + (lv < 4 ? 1 : 0), 'acidity of carboxylic acids', `${title}: the correct order of increasing acid strength for ${qlist.replace(/\(.\) /g, '')} is`, [...list].reverse().map((x) => strip(x[0])), ' &lt; ', S(`Acid strength follows the stability of the anion: ${why}.`, `pKa values: ${tab}.`, `Increasing acid strength means decreasing pKa: ${[...list].reverse().map((x) => strip(x[0])).join(' &lt; ')}.`), 'Increasing strength: weakest first.'));
}

// 5. reaction sequences: steps | answer | wrongs | level | why
