      const n = pick(rng, 0.05, 0.5, 0.05); const m = +(n * 106).toFixed(2); const alc = choose(rng, [true, false]); const M = alc ? 108 : 144; const ans = +(n / 2 * M).toFixed(2);
      return { q: `${m} g of benzaldehyde (M = 106 g/mol) is heated with conc. NaOH (Cannizzaro reaction, 100% yield). Find the mass of ${alc ? 'benzyl alcohol (M = 108 g/mol)' : 'sodium benzoate (M = 144 g/mol)'} formed.`, answer: ans, tol: tol1(ans), unit: 'g', n, M,
        sol: `<p>2 C<sub>6</sub>H<sub>5</sub>CHO + NaOH &rarr; C<sub>6</sub>H<sub>5</sub>CH<sub>2</sub>OH + C<sub>6</sub>H<sub>5</sub>COONa: half the aldehyde goes to each product.</p><p>Moles of aldehyde = ${m}/106 = ${fmt(n, 3)}; moles of each product = ${fmt(n / 2, 3)}.</p><p>Mass = ${fmt(n / 2, 3)} &times; ${M} = <b>${ans} g</b>.</p>`, trap: 'Only half of the aldehyde becomes each product.' };
